import{_ as r,o as t,c as e,a8 as s}from"./chunks/framework.BWjTbCIc.js";const h=JSON.parse('{"title":"圣保禄学校（中学部） · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-385eacf5","school_zh":"圣保禄学校（中学部）","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"圣保禄学校（中学部） · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-SPCS-FIRST","C2223-SPCS-SECOND"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-385eacf5/s1/2022-23-interview.md","filePath":"reports/school-385eacf5/s1/2022-23-interview.md"}'),p={name:"reports/school-385eacf5/s1/2022-23-interview.md"};function n(a,o,c,l,g,i){return t(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="圣保禄学校-中学部-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">圣保禄学校（中学部） · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#圣保禄学校-中学部-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;圣保禄学校（中学部） · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-385eacf5">← 返回圣保禄学校（中学部）资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-spcs-first" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-spcs-first" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-spcs-first}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>填表后分中英文面谈</strong></p><p>先填写英文表格，再分别由两位老师进行中文及英文面谈。部分六人一组等候，但面谈为个人任务。需准备及携带阅读报告所用的中英文图书，老师可能在电脑上查看报告。一个英语环节设九分钟计时，中文未明显计时。以下为不同学生的相近流程汇总。</p></blockquote><blockquote><p><strong>书面表达：</strong> 英语</p><p><strong>个人资料与反思</strong></p><p>表格约两页，除基本资料外，涉及兴趣、校内及校外比赛或奖项、假期打算读多少本书、英语程度自评、三个报读原因、自身特质及可为学校作出的贡献。有版本分别填写最多三项校内和三项校外奖项。</p><p><strong>感恩与感动经历</strong></p><p>写五件或五位值得感恩的事／人，或写一个令人感动的故事；不同版本有二选一，也有表格与作文分别填写的安排，另有人记得择校原因作文。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，口语未注明</p><p><strong>阅读报告与追问</strong></p><p>约三分钟介绍两本中文书，再谈其中一本的内容、喜欢的类型及原因。有老师问为什么应录取自己、假期读书计划、最感恩的事，以及欠交和抄袭功课的看法。</p><p><strong>抽题短讲</strong></p><p>从三张题卡抽一张，常见一分钟准备、一分钟表达。题目包括喜欢大自然还是城市生活；若有超能力，想到过去还是未来。另有两分钟讨论喜欢冒险前进还是稳步前进，并追问成为企业家后会否改变选择、男生女生可能如何选择。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>图书、朗读及角色理解</strong></p><p>介绍两本英文书或阅读报告，部分每本一分钟；老师可随机翻开书中一页要求朗读，也有朗读半页文章的版本。追问最不想成为哪个角色、自己与主角有什么相似之处、如何将角色特质应用于生活，以及若朋友被坏人欺负会怎样处理。部分学生没有被追问书中内容。</p><p><strong>抽题演说与日常交流</strong></p><p>三选一抽题，通常一分钟准备、一分钟表达；题目包括实体与网上课堂、影响自己的发明、疫情如何改变生活及从中学到什么。也有自我介绍、课外活动及择校问题。</p></blockquote><blockquote><p><strong>STEM：</strong> 语言未注明</p><p><strong>拆装与步骤记录</strong></p><p>拆开一个玩具或公仔，再重新组装，并写下完成步骤。</p></blockquote><h2 id="record-c2223-spcs-second" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-spcs-second" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-spcs-second}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>学生面谈：</strong> 英语为主；部分择校问题用中文</p><p><strong>学习、阅读及个人经历</strong></p><p>自我介绍、平日较常写中文还是英文、理想中学、喜欢的科目及原因；朗读一小段或半页英文。分享开心或难忘经历、当时感受及克服困难的方法。</p><p><strong>校园与开放问题</strong></p><p>介绍自己小学及其优点、如何吸引别人入读；介绍参加的活动，提出新点子并解释；若到荒岛会做什么。</p><p><strong>择校</strong></p><p>为何选择圣保禄、何时申请、面试了哪些学校、已有何种录取、若几间同时取录如何选择。部分与校长面谈；一位家长记得当场获知结果及随后办理注册，但不能据此预计每场都即时决定。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>选择与提问</strong></p><p>了解孩子为何希望入读，并让家长提出问题。</p></blockquote>',20)])])}const u=r(p,[["render",n]]);export{h as __pageData,u as default};
